const menu=document.querySelector('.menu'),nav=document.querySelector('nav');
menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'Close':'Menu'});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='Menu'}));
const motion=document.querySelector('#motion'),yard=document.querySelector('.yard');
let paused=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
function updateMotion(){yard.classList.toggle('paused',paused);motion.setAttribute('aria-pressed',String(paused));motion.setAttribute('aria-label',paused?'Play yard animation':'Pause yard animation');motion.innerHTML=paused?'▶ <span>Play animation</span>':'Ⅱ <span>Pause animation</span>'}updateMotion();
motion.addEventListener('click',()=>{paused=!paused;updateMotion()});
document.querySelectorAll('.product').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.product').forEach(p=>{p.classList.toggle('active',p===button);p.setAttribute('aria-pressed',String(p===button))});const product=button.dataset.product;document.querySelector('#selected-material').textContent=product;document.querySelector('#material').value=product;document.querySelector('#product-enquiry').href='https://wa.me/919048546940?text='+encodeURIComponent('Hello Kisan Sands, I would like to enquire about '+product+'.')}));
document.querySelector('#enquiry').addEventListener('submit',e=>{e.preventDefault();const material=document.querySelector('#material').value,quantity=document.querySelector('#quantity').value.trim(),location=document.querySelector('#location').value.trim(),details=document.querySelector('#details').value.trim();if(!location){document.querySelector('#location').focus();return}const text=['Hello Kisan Sands And Bricks, I would like a quote.','Material: '+material,quantity?'Quantity: '+quantity:'','Delivery location: '+location,details?'Details: '+details:''].filter(Boolean).join('\n');window.open('https://wa.me/919048546940?text='+encodeURIComponent(text),'_blank','noopener,noreferrer')});
